        if (!hasCameraPermission || selectedCameraId.isEmpty()) return@LaunchedEffect
        when (lifecycleEvent) {
            Lifecycle.Event.ON_PAUSE, Lifecycle.Event.ON_STOP -> handleCameraPause()
            Lifecycle.Event.ON_RESUME, Lifecycle.Event.ON_START -> handleCameraResume()
        }
    }

